def compute(vars):
    non_usd = vars["v1"]
    total = vars["v2"]

    if total == 0:
        return None

    value = (non_usd / total) * 100
    return {
        "value": value,
        "trace": {
            "non_usd": non_usd,
            "total": total,
            "ratio": non_usd / total,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
